import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const RECORD = /^ADR-(\d{3})-[a-z0-9-]+\.md$/;
const TITLE = /^# ADR-\d{3}: (.+)$/m;
const STATUS = /^\*\*Status:\*\*[ \t]*(.+)$/m;
const PARTLY_SUPERSEDED = /\*\*Superseded in part by/;
const FULLY_SUPERSEDED = /^\*\*Superseded by/m;
const INDEX_PATH = "docs/ADR-INDEX.md";

const HEADER = [
  "# ADR index",
  "",
  "Generated by `npm run adr-index`, which `adr-integrity.test.ts` holds current. One line per",
  "record: number, title, the status it records, any supersession a later record marked on it, and",
  "the file that owns it. Nothing here restates a record's argument, and a decision the index shows",
  "as superseded is still the record to read for why.",
  "",
];

function describe(path) {
  const name = basename(path);
  const text = readFileSync(path, "utf8");
  const number = RECORD.exec(name)[1];
  const title = TITLE.exec(text)?.[1] ?? name.replace(/\.md$/, "");
  const status = STATUS.exec(text)?.[1]?.trim() ?? "status not recorded";
  const superseded = PARTLY_SUPERSEDED.test(text)
    ? "superseded in part"
    : FULLY_SUPERSEDED.test(text)
      ? "superseded"
      : "";
  return { name, number, title, status, superseded };
}

export function records(docsDirectory = join(root, "docs")) {
  return readdirSync(docsDirectory)
    .filter((name) => RECORD.test(name))
    .sort((left, right) => Number(RECORD.exec(left)[1]) - Number(RECORD.exec(right)[1]))
    .map((name) => describe(join(docsDirectory, name)));
}

function lineFor(record) {
  const parts = [`- ADR-${record.number}`, record.title, record.status];
  if (record.superseded !== "") parts.push(record.superseded);
  parts.push(`[${record.name}](./${record.name})`);
  return parts.join(" — ");
}

export function render(rows) {
  return `${[...HEADER, ...rows.map(lineFor)].join("\n")}\n`;
}

/** The one question this asks of the committed index: is it what the records say right now. */
export function checkIndex(scanRoot = root) {
  const generated = render(records(join(scanRoot, "docs")));
  const index = join(scanRoot, INDEX_PATH);
  let committed = "";
  try {
    committed = readFileSync(index, "utf8");
  } catch {
    return [`${INDEX_PATH}: absent, run npm run adr-index`];
  }
  if (committed === generated) return [];
  const missing = generated
    .split("\n")
    .filter((row) => row.startsWith("- ADR-") && !committed.includes(row));
  const stale = committed
    .split("\n")
    .filter((row) => row.startsWith("- ADR-") && !generated.includes(row));
  return [
    `${INDEX_PATH} is out of date: run npm run adr-index`,
    ...missing.map((row) => `${INDEX_PATH}: missing ${row.slice(2, 18)}`),
    ...stale.map((row) => `${INDEX_PATH}: holds ${row.slice(2, 18)} from a record that moved`),
  ];
}

export function main(argv = process.argv.slice(2), scanRoot = root) {
  if (argv.includes("--write")) {
    writeFileSync(join(scanRoot, INDEX_PATH), render(records(join(scanRoot, "docs"))), "utf8");
    console.log(`wrote ${INDEX_PATH}`);
    return 0;
  }
  const violations = checkIndex(scanRoot);
  if (violations.length > 0) {
    console.error(violations.join("\n"));
    return 1;
  }
  console.log(`adr index current: ${records(join(scanRoot, "docs")).length} records`);
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) process.exitCode = main();
